# owner: platform
from rosterkit.errors import ProjectError


def absent_days(student, marks):
    """Sorted dates of the absent marks, checking owner."""
    for item in marks:
        if item.student_id != student.student_id:
            raise ProjectError("mark for another student")
    gone = filter(_is_absent, marks)
    return sorted(item.day for item in gone)


def absence_notice(student, marks):
    """Short parent notice listing the days missed."""
    days = absent_days(student, marks)
    if not days:
        raise ProjectError("no absences to report")
    dates = ", ".join(when.isoformat() for when in days)
    return _compose(student, len(days), dates)


def _compose(student, count, dates):
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {count} day(s): {dates}."


def _is_absent(item):
    return item.status == "absent"
